"""All Possible Full Binary Trees — recursion over the left subtree's size.

A full binary tree has an odd number of nodes; one node is the root and the rest
split into two odd-sized halves. Memoising on n avoids rebuilding shapes.

Time: O(2^n)   Space: O(2^n)
"""
from functools import lru_cache
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def allPossibleFBT(self, n: int) -> List:
        @lru_cache(maxsize=None)
        def build(count: int):
            if count % 2 == 0:
                return ()
            if count == 1:
                return (TreeNode(0),)
            trees = []
            for left_size in range(1, count - 1, 2):
                for left in build(left_size):
                    for right in build(count - 1 - left_size):
                        trees.append(TreeNode(0, left, right))
            return tuple(trees)

        return list(build(n))
